339	        //获取用户角色列表
340	        var GetUserRoles = function () {
341	            processing("数据加载中...");
342	            $.post("../Handler/Login.ashx", { "fun": "GetUserRoles" }, function (data) {
343	                if (data) {
344	                    var result = eval("(" + data + ")");
345	                    var errorMsg = result["ErrorMsg"];
346	                    if (errorMsg === "success") {
347	                        var roles = eval("(" + result["Data"] + ")");
348	                        $("#sltRole").html("");
349	                        $("#sltRole").append($("<option value=\"\">－请选择角色－</option>"));
350	                        $.each(roles, function (k, item) {
351	                            $("#sltRole").append($("<option value=\"" + item["CID"] + "\">" + item["NAME"] + "</option>"));
352	                        });
353	                        $.post("../Handler/Login.ashx", { "fun": "GetUserDefaultRole" }, function (d) {
354	                            if (d) {
355	                                var r = eval("(" + d + ")");
356	                                var error = r["ErrorMsg"];
357	                                if (error === "success") {
358	                                    var defaultData = eval("(" + r["Data"] + ")");
359	                                    if (!isNull(defaultData["DEFAULTROLE"])) {
360	                                        $("#sltRole").val(defaultData["DEFAULTROLE"]);
361	                                    }
362	                                    GetRoleMenuList(defaultData["DEFAULTROLE"], defaultData["DEFAULTHOMEURL"]);
363	                                }
364	                            }
365	                        });
366	                    } else {
367	                        $(document).tips({
368	                            content: result["Data"]
369	                        });
370	                    }
371	                }
372	            });
373	        }
374	        $("#sltRole").change(function () {
375	            processing("数据加载中...");
376	            GetRoleMenuList($(this).val(), "");
377	        });
378	        //获取菜单列表
379	        var GetRoleMenuList = function (roleCID, defaultHomeUrl) {
380	            $.post("../Handler/Login.ashx", { "fun": "GetRoleMenuList", roleCID: roleCID }, function (data) {
381	                if (data) {
382	                    var result = eval("(" + data + ")");
383	                    var errorMsg = result["ErrorMsg"];
384	                    if (errorMsg === "success") {
385	                        var menus = eval("(" + result["Data"] + ")");
386	                        $("#sltHome").html("");
387	                        $("#sltHome").append($("<option value=\"\">－请选择菜单－</option>"));
388	                        $.each(menus, function (k, item) {
389	                            $("#sltHome").append($("<option value=\"" + item["MENU_PATH"] + "\">" + item["NAME"] + "</option>"));
390	                        });
391	                        if (defaultHomeUrl) {
392	                            $("#sltHome").val(defaultHomeUrl);
393	                        }
394	                        unProcessing();
395	                    }
396	                    else {
397	                        $(document).tips({
398	                            content: result["Data"]
399	                        });
400	                    }
401	                }
402	            });
403	        }
