854	        /// <param name="context">请求信息</param>
855	        public void GetViewLoginInfoGrid(HttpContext context)
856	        {
857	            //页数
858	            int currentPage = int.Parse(context.Request["page"]);
859	
860	            //页尺长度
861	            int pageSize = int.Parse(context.Request["pageSize"]);
862	            if (pageSize == -1)
863	            {
864	                pageSize = int.MaxValue;
865	            }
866	
867	            string order = context.Request["sorts"];
868	
869	            //查询条件
870	            string filters = context.Request["filters"];
871	            T_PORTAL_LOGININFO_BL db = new T_PORTAL_LOGININFO_BL();
872	            SearchGroup rootSearch = JsonConvert.DeserializeObject<SearchGroup>(filters);
873	            string wheresql;
874	            object[] wherevalue;
875	            string error;
876	            bool objSg = UIHelper.GetWhereSqlBySearchGroup(rootSearch, out wheresql, out wherevalue, out error, 0);
877	            if (!objSg)
878	            {
879	                context.Response.Write(error);
880	                return;
881	            }
882	
883	            //格式化排序字段
884	            object[] strs = JsonConvert.DeserializeObject<object[]>(order);
885	            SearchOrder[] ordersArr = new SearchOrder[strs.Length];
886	            int orderArrIndex = 0;
887	            foreach (var item in strs)
888	            {
889	                SearchOrder sOrder = new SearchOrder();
890	                sOrder.Field = ((Newtonsoft.Json.Linq.JToken)item).First().ToString();
891	                if (((Newtonsoft.Json.Linq.JToken)item).Last().ToString() == "asc")
892	                {
893	                    sOrder.Rule = SearchOrderRule.ASC;
894	                }
895	                else
896	                {
897	                    sOrder.Rule = SearchOrderRule.DESC;
898	                }
899	
